import{_ as a,C as s,o,c as n,a2 as t,E as l}from"./chunks/framework.BSaF8iZ6.js";const b=JSON.parse('{"title":"Seller Panel Overview","description":"","frontmatter":{},"headers":[],"relativePath":"seller-panel/overview.md","filePath":"seller-panel/overview.md","lastUpdated":1789411447000}'),d={name:"seller-panel/overview.md"};function i(h,e,g,p,u,c){const r=s("ImagePopup");return o(),n("div",null,[e[0]||(e[0]=t('<h1 id="seller-panel-overview" tabindex="-1">Seller Panel Overview <a class="header-anchor" href="#seller-panel-overview" aria-label="Permalink to &quot;Seller Panel Overview&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>The Seller Panel is where sellers and their team run their shop. It opens at <code>/seller</code> on your store&#39;s address, and you sign in on <strong>Seller Login</strong>. See <a href="./../sellers/becoming-a-seller">Becoming a Seller</a>.</p>',3)),l(r,{src:"/images/seller-panel/seller-panel.png",alt:"The Seller Panel with its header, sidebar and dashboard"}),e[1]||(e[1]=t('<h2 id="the-header" tabindex="-1">The header <a class="header-anchor" href="#the-header" aria-label="Permalink to &quot;The header&quot;">​</a></h2><ul><li><strong>Mega Search</strong> — type to find your <strong>Products</strong>, <strong>Orders</strong> and <strong>Customers</strong>. Click a product or order to open it, or use <strong>Explore all</strong> to see every match. Customer results can&#39;t be clicked, so use <strong>Explore all</strong> to find them in your customers list.</li><li><strong>Toggle Theme</strong> — switch between the light and dark look. Your choice is kept in your browser.</li><li><strong>Home Page</strong> — opens the store&#39;s home page.</li><li><strong>Visit Shop</strong> — opens your shop page as customers see it. It appears when the store makes seller shops public.</li><li><strong>Profile menu</strong> — <strong>My Profile</strong> opens your shop details, and <strong>Logout</strong> signs you out.</li></ul><p>When the store uses subscription plans, your plan ends within nine days and no next plan is lined up, the header also shows <strong>Subscription expires in:</strong> with a countdown. Click it to choose your next plan.</p><h2 id="the-sidebar" tabindex="-1">The sidebar <a class="header-anchor" href="#the-sidebar" aria-label="Permalink to &quot;The sidebar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>What you do there</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td>Follow sales, orders and what needs your attention. See <a href="./dashboard">Dashboard</a>.</td></tr><tr><td><strong>Catalog</strong></td><td>List products, see your products and bulk upload. See <a href="./../catalog/product-management">Product Management</a>.</td></tr><tr><td><strong>Inventories</strong></td><td>Update stock and manage your inventory sources. See <a href="./../inventory/manage-inventory">Manage Inventory</a>.</td></tr><tr><td><strong>Pricing</strong></td><td>Update prices, sale prices and tier prices. See <a href="./../pricing/manage-pricing">Manage Pricing</a>.</td></tr><tr><td><strong>Marketing</strong></td><td>Run product discounts and checkout deals. See <a href="./../marketing/product-discounts">Product Discounts</a>.</td></tr><tr><td><strong>Sales</strong></td><td>Handle orders, returns, bookings and your transactions. See <a href="./../orders/order-management">Order Management</a>.</td></tr><tr><td><strong>Performance</strong></td><td>Check account health and read reviews. See <a href="./../sellers/seller-account-health">Account Health</a>.</td></tr><tr><td><strong>Reporting</strong></td><td>See sales, customer and product reports. See <a href="./../reporting/seller-reporting">Seller Reports</a>.</td></tr><tr><td><strong>Communication</strong></td><td>Message the store admin and reply to customers. See <a href="./../customers/communications">Communications</a>.</td></tr><tr><td><strong>Customers</strong></td><td>See the customers who bought from you. See <a href="./../customers/customer-management">Seller Customers</a>.</td></tr><tr><td><strong>Plans</strong></td><td>Choose a subscription plan. It appears for the shop owner when the store uses plans. See <a href="./../subscriptions/choosing-a-plan">Choosing a Plan</a>.</td></tr><tr><td><strong>Settings</strong></td><td>Change your password and language, and manage your team. See <a href="./account-settings">Account Settings</a> and <a href="./users-and-roles">Users &amp; Roles</a>.</td></tr></tbody></table><p>Click <strong>Collapse</strong> at the bottom of the sidebar to show icons only.</p><p>The pages inside a menu also appear as tabs at the top of the page, so you can move between them without opening the sidebar.</p><h2 id="what-team-members-see" tabindex="-1">What team members see <a class="header-anchor" href="#what-team-members-see" aria-label="Permalink to &quot;What team members see&quot;">​</a></h2><p>Team members sign in on the same <strong>Seller Login</strong> page. They see only the menus their role allows, and they work with the shop&#39;s data. They can&#39;t open <strong>My Profile</strong>, which is only for the shop owner. See <a href="./users-and-roles">Users &amp; Roles</a>.</p><h2 id="change-the-panel-language" tabindex="-1">Change the panel language <a class="header-anchor" href="#change-the-panel-language" aria-label="Permalink to &quot;Change the panel language&quot;">​</a></h2><p>The Seller Panel uses the language chosen under <strong>Settings &gt;&gt; General</strong>. See <a href="./account-settings">Account Settings</a>.</p>',11))])}const S=a(d,[["render",i]]);export{b as __pageData,S as default};
